function findTickets(obj) {
    var tickets = [];
    var visited = new WeakSet();

    function walk(value) {
        if (!value || typeof value !== "object") {
            return;
        }

        if (visited.has(value)) {
            return;
        }
        visited.add(value);

        if (Array.isArray(value)) {
            value.forEach(walk);
            return;
        }

        if (
            Object.prototype.hasOwnProperty.call(
                value, "ticketNo"
            )
        ) {
            tickets.push(value);
        }

        Object.keys(value).forEach(function(key) {
            walk(value[key]);
        });
    }

    walk(obj);
    return tickets;
}

